  content: "";
  position: absolute;
  inset: 5px;
  border: 1px dashed rgba(232, 232, 234, 0.26);
  border-radius: 3px;
  background:
    var(--lm-star4) left 4px top 4px / 10px no-repeat,
    var(--lm-star4) right 4px top 4px / 10px no-repeat,
    var(--lm-star4) left 4px bottom 4px / 10px no-repeat,
    var(--lm-star4) right 4px bottom 4px / 10px no-repeat;
  pointer-events: none;
}
#chat > .mes:first-child {
  margin-top: 8px;
}
.last_mes {
  margin-bottom: 10px !important;
}

